package main

import "fmt"

func saludar(nombre string) {
	fmt.Println("Hola,", nombre)
}

func main() {
	saludar("Bryan") // Hola, Bryan
	saludar("Franc") // Hola, Franc
}

package main

import "fmt"

func sumar(a, b int) int {
	return a + b
}

func esPositivo(n int) bool {
	return n > 0
}

func main() {
	total := sumar(3, 4)
	fmt.Println(total) // 7

	fmt.Println(esPositivo(-2))
	// Sale: false
}

package main

import "fmt"

func dividir(a, b int) (int, int) {
	return a / b, a % b
}

func main() {
	c, r := dividir(17, 5)
	fmt.Println(c, r) // 3 2

	_, resto := dividir(9, 2)
	fmt.Println(resto) // 1
}

package main

import "fmt"

func doble(n int) int {
